class View:
    def __init__(self):
        self.rows=[]
        self.notes={}
        self.loading=False
        self.error=None
        self.seq=0
        self.latest_request_id = None

    def begin(self, query):
        self.seq += 1
        request_id = self.seq
        self.latest_request_id = request_id
        self.error = None
        return request_id

    def finish(self, request_id, rows):
        if request_id != self.latest_request_id:
            return False
        self.rows = rows
        self.loading = True
        return True
